def solve(inputs: dict) -> float:
    n = str(int(inputs['n']))
    digits = [int(d) for d in n]
    # From right, double every second digit (positions 2, 4, 6, ... from right)
    result = []
    for i, d in enumerate(reversed(digits)):
        if (i + 1) % 2 == 0:  # every second digit from right (2nd, 4th, ...)
            d *= 2
            if d > 9:
                d -= 9
        result.append(d)
    return float(sum(result))

