import math
from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    mode = int(inputs.get('mode', 0))

    if mode == 0:  # factorial mod
        n = int(inputs['n'])
        mod = int(inputs['mod'])
        result = 1
        for i in range(1, n+1):
            result = (result * i) % mod
        return float(result)

    elif mode == 1:  # look and say
        s = str(int(inputs['n']))
        k = int(inputs['k'])
        for _ in range(k):
            new_s = ''
            i = 0
            while i < len(s):
                c = s[i]
                count = 1
                while i + count < len(s) and s[i+count] == c:
                    count += 1
                new_s += str(count) + c
                i += count
            s = new_s
        return float(int(s))

    elif mode == 2:  # power mod
        base = int(inputs['base'])
        exp = int(inputs['exp'])
        mod = int(inputs['mod'])
        return float(pow(base, exp, mod))

    elif mode == 3:  # sum of digits
        n = str(int(inputs['n']))
        return float(sum(int(d) for d in n))

    elif mode == 4:  # lcm of list
        vals = [int(inputs[f'v{i}']) for i in range(int(inputs['n']))]
        def lcm(a, b): return a * b // gcd(a, b)
        return float(reduce(lcm, vals))

    elif mode == 5:  # count primes / primality
        n = int(inputs['n'])
        if n < 2: return 0.0
        for i in range(2, int(n**0.5)+1):
            if n % i == 0: return 0.0
        return 1.0

    elif mode == 6:  # nth prime
        n = int(inputs['n'])
        count = 0
        num = 1
        while count < n:
            num += 1
            is_p = True
            for i in range(2, int(num**0.5)+1):
                if num % i == 0:
                    is_p = False
                    break
            if is_p:
                count += 1
        return float(num)

    elif mode == 7:  # arbitrary expression: a^b mod m sum etc
        # collatz steps
        n = int(inputs['n'])
        steps = 0
        while n != 1:
            if n % 2 == 0:
                n //= 2
            else:
                n = 3*n + 1
            steps += 1
        return float(steps)

    elif mode == 8:  # digit product
        n = str(int(inputs['n']))
        p = 1
        for d in n:
            p *= int(d)
        return float(p)

    elif mode == 9:  # reverse number
        n = str(int(inputs['n']))
        return float(int(n[::-1]))

    return 0.0

